136: 	updatedAt := time.Now().UTC()
137: 	result, err := s.db.Exec(
138: 		`UPDATE todos SET title = ?, completed = ?, updated_at = ? WHERE id = ?`,
139: 		title,
140: 		input.Completed,
141: 		updatedAt.Format(time.RFC3339Nano),
142: 		id,
143: 	)
144: 	if err != nil {
145: 		return Todo{}, fmt.Errorf("update todo: %w", err)
146: 	}
147: 	affected, err := result.RowsAffected()
148: 	if err != nil {
149: 		return Todo{}, fmt.Errorf("read updated row count: %w", err)
150: 	}
151: 	if affected == 0 {
152: 		return Todo{}, errTodoNotFound
153: 	}
154: 	return s.Get(id)
155: }
