161: func scanTodo(row rowScanner) (Todo, error) {
162: 	var todo Todo
163: 	var completed int
164: 	var createdAt string
165: 	var updatedAt string
166: 	if err := row.Scan(&todo.ID, &todo.Title, &completed, &createdAt, &updatedAt); err != nil {
167: 		return Todo{}, err
168: 	}
169: 
170: 	var err error
171: 	todo.CreatedAt, err = time.Parse(time.RFC3339Nano, createdAt)
172: 	if err != nil {
173: 		return Todo{}, fmt.Errorf("parse todo created time: %w", err)
174: 	}
175: 	todo.UpdatedAt, err = time.Parse(time.RFC3339Nano, updatedAt)
176: 	if err != nil {
177: 		return Todo{}, fmt.Errorf("parse todo updated time: %w", err)
178: 	}
179: 	todo.Completed = completed != 0
180: 	return todo, nil
181: }
